const uint32_t *keymap_get_default(uint8_t sys, uint8_t map)
{
    if ((sys >= KBD_SYS_MAX) || (map >= KBD_MAP_MAX)) {
        return NULL;
    }
    return keymap[sys][map];
}

uint8_t keymap_get_ki(uint8_t si)
{
    if (si >= sizeof(ks2ki)) {
        return 0xff;
    }
    return ks2ki[si];
}
